def countSimilarGroups(words):
    ws = words.split(",")
    n = len(ws)
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[ra] = rb

    index = {}
    for i, w in enumerate(ws):
        if w in index:
            union(i, index[w])
        else:
            index[w] = i
    for i, w in enumerate(ws):
        if index[w] != i:
            continue
        L = len(w)
        chars = list(w)
        for a in range(L):
            for b in range(a + 1, L):
                if chars[a] == chars[b]:
                    continue
                chars[a], chars[b] = chars[b], chars[a]
                j = index.get("".join(chars))
                if j is not None:
                    union(i, j)
                chars[a], chars[b] = chars[b], chars[a]
    return sum(1 for i in range(n) if find(i) == i)
